package main

import "math/big"

// Rates mirror RATES in src/pricing.ts: EUR -> currency, exact decimals.
var Rates = map[string]*big.Rat{
	"EUR": ratOf("1"),
	"USD": ratOf("1.0825"),
	"UAH": ratOf("45.6"),
}

func ratOf(s string) *big.Rat {
	r, ok := new(big.Rat).SetString(s)
	if !ok {
		panic("bad decimal " + s)
	}
	return r
}

// cents rounds r half-even to an integer (ADR-007). No floats involved.
func cents(r *big.Rat) int64 {
	num, den := r.Num(), r.Denom()
	q, m := new(big.Int).QuoRem(num, den, new(big.Int)) // truncated toward zero
	twice := new(big.Int).Abs(m)
	twice.Lsh(twice, 1)
	switch c := twice.Cmp(den); {
	case c > 0, c == 0 && q.Bit(0) == 1:
		if num.Sign() < 0 {
			q.Sub(q, big.NewInt(1))
		} else {
			q.Add(q, big.NewInt(1))
		}
	}
	return q.Int64()
}
EOF
cat > go/money_test.go <<'EOF'
package main

import "testing"

func TestCentsHalfEven(t *testing.T) {
	cases := map[string]int64{
		"0.5": 0, "1.5": 2, "2.5": 2, "3.5": 4, // ties go to even, both ways
		"2.4999": 2, "2.5001": 3, "0": 0, "7": 7,
		"-0.5": 0, "-1.5": -2, "-2.5": -2, "-2.6": -3, "-2.4": -2,
		"3607.9725": 3608, // 3333 x 1.0825
	}
	for in, want := range cases {
		if got := cents(ratOf(in)); got != want {
			t.Errorf("cents(%s) = %d, want %d", in, got, want)
		}
	}
}

func TestCentsUnitConversion(t *testing.T) {
	r := ratOf("3333")
	r.Mul(r, Rates["USD"])
	if got := cents(r); got != 3608 {
		t.Fatalf("3333 x 1.0825 = %d, want 3608", got)
	}
}
EOF
cat > go/prices.go <<'EOF'
package main

import (
	"math/big"
	"net/http"
	"strings"
)

type priceResponse struct {
	SKU        string `json:"sku"`
	Currency   string `json:"currency"`
	BaseCents  int64  `json:"baseCents"`
}

type apiError struct {
	Error string `json:"error"`
}

// unitPrice mirrors src/pricing.ts unitPrice: SKU first (404), then currency (422).
func unitPrice(sku, currency string) (int64, int, string) {
	p, ok := FindProduct(sku)
	if !ok {
		return 0, http.StatusNotFound, "unknown sku " + sku
	}
	rate, ok := Rates[currency]
	if !ok {
		return 0, http.StatusUnprocessableEntity, "unsupported currency " + currency
	}
	return cents(new(big.Rat).Mul(new(big.Rat).SetInt64(p.BaseEurCents), rate)), 0, ""
}

// queryCurrency matches Express 5 String(req.query.currency ?? "EUR"): absent
// key -> EUR, repeated key -> values joined with ",". Keys are exact.
func queryCurrency(r *http.Request) string {
	vals, ok := r.URL.Query()["currency"]
	if !ok {
		return "EUR"
	}
	return strings.Join(vals, ",")
}

func handlePrice(w http.ResponseWriter, r *http.Request) {
	sku := r.PathValue("sku")
	currency := queryCurrency(r)
	base, status, msg := unitPrice(sku, currency)
	if status != 0 {
		writeJSON(w, status, apiError{msg})
		return
	}
	writeJSON(w, http.StatusOK, priceResponse{sku, currency, base})
}
EOF
